import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { curryRight } from "./src/function/curryRight.js";
{
{
{
const fn = (a, b, c) => ({ a, b, c });
        const curried = curryRight(fn);
        expectTypeOf(curried).parameters.toEqualTypeOf();
        expectTypeOf(curried(true)).parameters.toEqualTypeOf();
        expectTypeOf(curried(true)).not.toEqualTypeOf();
        expectTypeOf(curried(true)('a')).parameters.toEqualTypeOf();
        expectTypeOf(curried(true)('a')).not.toEqualTypeOf();
        expectTypeOf(curried(true)('a')(1)).toEqualTypeOf();
}
}
}
